def validation_metrics(
    accum: dict[str, list[np.ndarray]],
    loss_totals: dict[str, float],
    item_count: int,
) -> dict[str, Any]:
    graph_logits = np.concatenate(accum["attack_logits"])
    graph_scores = 1.0 / (1.0 + np.exp(-graph_logits))
    graph_targets = np.concatenate(accum["graph_targets"]).astype(
        np.int64
    )
    active_mask = graph_targets == 1

    graph = binary_metrics(graph_scores, graph_targets)
    graph["auroc"] = binary_auroc(
        graph_scores,
        graph_targets,
    )
    graph["average_precision"] = binary_average_precision(
        graph_scores,
        graph_targets,
    )

    count_logits = np.concatenate(accum["count_logits"])
    count_targets = np.concatenate(accum["count_targets"]).astype(
        np.int64
    )
    active_count_logits = count_logits[active_mask]
    active_count_targets = count_targets[active_mask]
    count_predictions = (
        np.argmax(active_count_logits, axis=1) + 1
    )
    count_accuracy = float(
        np.mean(count_predictions == active_count_targets)
    )
    count_macro_f1 = multiclass_macro_f1(
        count_predictions,
        active_count_targets,
        COUNT_CLASS_VALUES,
    )

    roles = {}
    for role in ("source", "transit", "victim", "path"):
        logits = np.concatenate(accum[f"{role}_logits"])
        scores = 1.0 / (1.0 + np.exp(-logits))
        targets = np.concatenate(
            accum[f"{role}_targets"]
        ).astype(np.int64)
        flattened = binary_metrics(
            scores.reshape(-1),
            targets.reshape(-1),
        )
        flattened["auroc"] = binary_auroc(
            scores.reshape(-1),
            targets.reshape(-1),
        )
        flattened["average_precision"] = (
            binary_average_precision(
                scores.reshape(-1),
                targets.reshape(-1),
            )
        )
        flattened.update(
            exact_multilabel(
                scores,
                targets,
                active_mask,
            )
        )
        roles[role] = flattened

    components = [
        graph["auroc"],
        graph["average_precision"],
        count_macro_f1,
        roles["source"]["average_precision"],
        roles["transit"]["average_precision"],
        roles["victim"]["average_precision"],
        roles["path"]["average_precision"],
    ]
    if not all(math.isfinite(value) for value in components):
        raise RuntimeError(
            f"non-finite validation selection component: "
            f"{components}"
        )
    selection_score = float(np.mean(components))

    return {
        "loss": {
            key: value / item_count
            for key, value in loss_totals.items()
        },
        "selection_score": selection_score,
        "selection_components": {
            "graph_auroc": graph["auroc"],
            "graph_average_precision": (
                graph["average_precision"]
            ),
            "count_active_macro_f1": count_macro_f1,
            "source_average_precision": (
                roles["source"]["average_precision"]
            ),
            "transit_average_precision": (
                roles["transit"]["average_precision"]
            ),
            "victim_average_precision": (
                roles["victim"]["average_precision"]
            ),
            "path_average_precision": (
                roles["path"]["average_precision"]
            ),
        },
        "graph": graph,
        "count_active": {
            "accuracy": count_accuracy,
            "macro_f1": count_macro_f1,
            "items": int(active_mask.sum()),
        },
        "roles": roles,
        "threshold_policy": {
            "reporting_threshold": 0.5,
            "threshold_tuning_performed": False,
            "selection_metrics_are_threshold_free_except_count_macro_f1": True,
        },
    }

def sha256_file(path: Path) -> str:
    digest = hashlib.sha256()
    with path.open("rb") as handle:
        for block in iter(lambda: handle.read(1024 * 1024), b""):
            digest.update(block)
    return digest.hexdigest()

def exact_multilabel(
    scores: np.ndarray,
    targets: np.ndarray,
    active_mask: np.ndarray,
    threshold: float = 0.5,
) -> dict[str, float]:
    scores = np.asarray(scores, dtype=np.float64)
    targets = np.asarray(targets, dtype=np.int64)
    predictions = (scores >= threshold).astype(np.int64)
    all_exact = float(
        np.mean(np.all(predictions == targets, axis=1))
    )
    if np.any(active_mask):
        active_exact = float(
            np.mean(
                np.all(
                    predictions[active_mask]
                    == targets[active_mask],
                    axis=1,
                )
            )
        )
    else:
        active_exact = float("nan")
    return {
        "exact_all": all_exact,
        "exact_active": active_exact,
    }

def compute_losses(
    outputs: dict[str, torch.Tensor],
    batch: dict[str, torch.Tensor],
    graph_pos_weight: torch.Tensor,
    role_pos_weights: dict[str, torch.Tensor],
) -> dict[str, torch.Tensor]:
    active = batch["graph"] > 0.5
    if not bool(active.any()):
        count_loss = outputs["count_logits"].sum() * 0.0
    else:
        active_targets = batch["count"][active] - 1
        if not bool(
            ((active_targets >= 0) & (active_targets <= 3)).all()
        ):
            raise RuntimeError(
                "active Count4 targets are outside 0..3"
            )
        count_loss = F.cross_entropy(
            outputs["count_logits"][active],
            active_targets,
        )

    losses = {
        "graph": F.binary_cross_entropy_with_logits(
            outputs["attack_logits"],
            batch["graph"],
            pos_weight=graph_pos_weight,
        ),
        "count": count_loss,
        "source": F.binary_cross_entropy_with_logits(
            outputs["source_logits"],
            batch["source"],
            pos_weight=role_pos_weights["source"],
        ),
        "transit": F.binary_cross_entropy_with_logits(
            outputs["transit_logits"],
            batch["transit"],
            pos_weight=role_pos_weights["transit"],
        ),
        "victim": F.binary_cross_entropy_with_logits(
            outputs["victim_logits"],
            batch["victim"],
            pos_weight=role_pos_weights["victim"],
        ),
        "path": F.binary_cross_entropy_with_logits(
            outputs["path_logits"],
            batch["path"],
            pos_weight=role_pos_weights["path"],
        ),
    }
    losses["total"] = sum(losses.values())
    if not all(torch.isfinite(value) for value in losses.values()):
        raise RuntimeError("non-finite multitask loss")
    return losses

def binary_average_precision(
    scores: np.ndarray,
    targets: np.ndarray,
) -> float:
    scores = np.asarray(scores, dtype=np.float64).reshape(-1)
    targets = np.asarray(targets, dtype=np.int64).reshape(-1)
    positive_count = int((targets == 1).sum())
    if positive_count == 0:
        return float("nan")
    order = np.argsort(-scores, kind="mergesort")
    ordered_targets = targets[order]
    cumulative_positive = np.cumsum(ordered_targets == 1)
    positions = np.arange(1, len(targets) + 1)
    precision_at_k = cumulative_positive / positions
    return float(
        precision_at_k[ordered_targets == 1].sum()
        / positive_count
    )

def binary_auroc(
    scores: np.ndarray,
    targets: np.ndarray,
) -> float:
    scores = np.asarray(scores, dtype=np.float64).reshape(-1)
    targets = np.asarray(targets, dtype=np.int64).reshape(-1)
    positive = targets == 1
    negative = targets == 0
    n_positive = int(positive.sum())
    n_negative = int(negative.sum())
    if n_positive == 0 or n_negative == 0:
        return float("nan")
    ranks = average_ranks(scores)
    rank_sum_positive = float(ranks[positive].sum())
    return (
        rank_sum_positive
        - n_positive * (n_positive + 1) / 2.0
    ) / (n_positive * n_negative)

def average_ranks(values: np.ndarray) -> np.ndarray:
    order = np.argsort(values, kind="mergesort")
    sorted_values = values[order]
    ranks = np.empty(len(values), dtype=np.float64)
    start = 0
    while start < len(values):
        end = start + 1
        while (
            end < len(values)
            and sorted_values[end] == sorted_values[start]
        ):
            end += 1
        average_rank = (start + 1 + end) / 2.0
        ranks[order[start:end]] = average_rank
        start = end
    return ranks

def threshold_metrics(probabilities, targets) -> dict[str, float]:
    p = np.asarray(probabilities, dtype=np.float64).reshape(-1); y = np.asarray(targets, dtype=np.int64).reshape(-1)
    pred = (p >= 0.5).astype(np.int64)
    tp = int(((pred == 1) & (y == 1)).sum()); fp = int(((pred == 1) & (y == 0)).sum())
    fn = int(((pred == 0) & (y == 1)).sum()); tn = int(((pred == 0) & (y == 0)).sum())
    precision = tp/(tp+fp) if tp+fp else 0.0; recall = tp/(tp+fn) if tp+fn else 0.0
    f1 = 2*precision*recall/(precision+recall) if precision+recall else 0.0
    return {'accuracy': (tp+tn)/max(1,tp+fp+fn+tn), 'precision': precision, 'recall': recall,
            'f1': f1, 'fpr': fp/(fp+tn) if fp+tn else 0.0, 'tp': tp, 'fp': fp, 'fn': fn, 'tn': tn}

def sha(path: Path) -> str:
    h = hashlib.sha256()
    with path.open('rb') as f:
        for block in iter(lambda: f.read(1024 * 1024), b''):
            h.update(block)
    return h.hexdigest()

def move(batch, device):
    mapping = {'x':('x',torch.float32), 'mask':('physical_port_mask',torch.float32),
               'graph':('y_attack',torch.float32), 'count':('y_attacker_count',torch.long),
               'source':('y_source',torch.float32), 'transit':('y_transit',torch.float32),
               'victim':('y_victim',torch.float32), 'path':('y_attack_path',torch.float32)}
    out = {}
    for dst,(src,dtype) in mapping.items():
        if src not in batch: raise RuntimeError(f'missing {src}; keys={sorted(batch)}')
        value = batch[src].to(device=device, dtype=dtype, non_blocking=device.type=='cuda')
        out[dst] = value.reshape(-1) if dst in ('graph','count') else value
    return out

def macro_f1(predictions, targets) -> float:
    pred = np.asarray(predictions); y = np.asarray(targets); values = []
    for c in (1,2,3,4):
        pp, yy = pred == c, y == c
        tp = int((pp & yy).sum()); fp = int((pp & ~yy).sum()); fn = int((~pp & yy).sum())
        precision = tp/(tp+fp) if tp+fp else 0.0; recall = tp/(tp+fn) if tp+fn else 0.0
        values.append(2*precision*recall/(precision+recall) if precision+recall else 0.0)
    return float(np.mean(values))

def import_file(path: Path, name: str):
    spec = importlib.util.spec_from_file_location(name, path)
    if spec is None or spec.loader is None: raise RuntimeError(f'cannot import {path}')
    mod = importlib.util.module_from_spec(spec); sys.modules[name] = mod; spec.loader.exec_module(mod)
    return mod

def exact_active(probabilities, targets, active) -> float:
    pred = (np.asarray(probabilities) >= 0.5).astype(np.int64); y = np.asarray(targets, dtype=np.int64)
    return float(np.mean(np.all(pred[active] == y[active], axis=1)))

def auroc(scores, targets) -> float:
    s = np.asarray(scores, dtype=np.float64).reshape(-1); y = np.asarray(targets, dtype=np.int64).reshape(-1)
    pos = y == 1; neg = y == 0; np_, nn_ = int(pos.sum()), int(neg.sum())
    if np_ == 0 or nn_ == 0: return float('nan')
    return float((ranks(s)[pos].sum() - np_ * (np_ + 1) / 2.0) / (np_ * nn_))

def ap(scores, targets) -> float:
    s = np.asarray(scores, dtype=np.float64).reshape(-1); y = np.asarray(targets, dtype=np.int64).reshape(-1)
    npos = int((y == 1).sum())
    if npos == 0: return float('nan')
    order = np.argsort(-s, kind='mergesort'); yy = y[order]
    precision = np.cumsum(yy == 1) / np.arange(1, len(yy) + 1)
    return float(precision[yy == 1].sum() / npos)

def seed_all(seed: int):
    random.seed(seed); np.random.seed(seed); torch.manual_seed(seed); torch.cuda.manual_seed_all(seed)
    if torch.cuda.is_available():
        torch.backends.cudnn.deterministic = True
        torch.backends.cudnn.benchmark = False

def stable_sigmoid(values: np.ndarray) -> np.ndarray:
    return torch.sigmoid(
        torch.as_tensor(values, dtype=torch.float64)
    ).cpu().numpy()

def evaluate_policy(
    name: str,
    graph_threshold: float,
    role_thresholds: dict[str, float],
    arrays: dict[str, np.ndarray],
    labels: dict[str, np.ndarray],
) -> tuple[dict[str, Any], dict[str, np.ndarray]]:
    probabilities = {
        "graph": stable_sigmoid(arrays["attack_logits"]),
        "source": stable_sigmoid(arrays["source_logits"]),
        "transit": stable_sigmoid(arrays["transit_logits"]),
        "victim": stable_sigmoid(arrays["victim_logits"]),
        "path": stable_sigmoid(arrays["path_logits"]),
    }
    graph_prediction = (
        probabilities["graph"] >= graph_threshold
    ).astype(np.uint8)
    count_prediction = (
        np.argmax(arrays["count_logits"], axis=1) + 1
    ).astype(np.int8)
    role_predictions = {
        role: (
            probabilities[role] >= role_thresholds[role]
        ).astype(np.uint8)
        for role in ("source", "transit", "victim", "path")
    }

    active_truth = labels["graph"] == 1
    metrics = {
        "policy": name,
        "thresholds": {
            "graph": graph_threshold,
            **role_thresholds,
        },
        "graph": {
            **binary_metrics(
                graph_prediction,
                labels["graph"],
            ),
            "auroc_raw_logits": binary_auroc(
                arrays["attack_logits"],
                labels["graph"],
            ),
            "average_precision_raw_logits": (
                binary_average_precision(
                    arrays["attack_logits"],
                    labels["graph"],
                )
            ),
        },
        "count_active": multiclass_metrics_active(
            count_prediction[active_truth],
            labels["count"][active_truth],
        ),
        "roles": {
            role: role_metrics(
                role_predictions[role],
                labels[role],
                arrays[f"{role}_logits"],
                active_truth,
            )
            for role in ("source", "transit", "victim", "path")
        },
        "strict": strict_exactness(
            graph_prediction,
            count_prediction,
            role_predictions,
            labels,
        ),
        "cross_head_consistency": consistency_audit(
            graph_prediction,
            count_prediction,
            role_predictions,
        ),
        "graph_gating_applied": False,
        "route_legality_enforced": False,
        "count_source_consistency_enforced": False,
    }
    outputs = {
        "graph_prediction": graph_prediction,
        "count_prediction": count_prediction,
        "source_prediction": role_predictions["source"],
        "transit_prediction": role_predictions["transit"],
        "victim_prediction": role_predictions["victim"],
        "path_prediction": role_predictions["path"],
    }
    return metrics, outputs

def sha256_file(path: Path) -> str:
    digest = hashlib.sha256()
    with path.open("rb") as handle:
        for block in iter(lambda: handle.read(1024 * 1024), b""):
            digest.update(block)
    return digest.hexdigest()

def role_metrics(
    prediction: np.ndarray,
    target: np.ndarray,
    scores: np.ndarray,
    active_truth: np.ndarray,
) -> dict[str, Any]:
    prediction = np.asarray(prediction, dtype=np.uint8)
    target = np.asarray(target, dtype=np.uint8)
    flattened = binary_metrics(
        prediction.reshape(-1),
        target.reshape(-1),
    )
    exact_all = float(
        np.mean(np.all(prediction == target, axis=1))
    )
    exact_active = float(
        np.mean(
            np.all(
                prediction[active_truth] == target[active_truth],
                axis=1,
            )
        )
    )
    exact_inactive = float(
        np.mean(
            np.all(
                prediction[~active_truth] == target[~active_truth],
                axis=1,
            )
        )
    )
    predicted_cardinality = prediction.sum(axis=1)
    true_cardinality = target.sum(axis=1)
    return {
        "flattened": flattened,
        "average_precision_raw_logits": binary_average_precision(
            scores.reshape(-1),
            target.reshape(-1),
        ),
        "auroc_raw_logits": binary_auroc(
            scores.reshape(-1),
            target.reshape(-1),
        ),
        "exact_all": exact_all,
        "exact_active": exact_active,
        "exact_inactive": exact_inactive,
        "mean_predicted_cardinality_all": float(
            predicted_cardinality.mean()
        ),
        "mean_predicted_cardinality_active": float(
            predicted_cardinality[active_truth].mean()
        ),
        "mean_true_cardinality_active": float(
            true_cardinality[active_truth].mean()
        ),
    }

def parse_args() -> argparse.Namespace:
    parser = argparse.ArgumentParser()
    parser.add_argument("--repo", required=True)
    parser.add_argument("--output-dir", required=True)
    parser.add_argument("--installed-script", required=True)
    return parser.parse_args()

def main() -> int:
    args = parse_args()

    repo = Path(args.repo).expanduser().resolve()
    output_dir = Path(args.output_dir).expanduser().resolve()
    installed_script = Path(
        args.installed_script
    ).expanduser().resolve()
    output_dir.mkdir(parents=True, exist_ok=True)

    report_path = output_dir / f"{STAGE}_REPORT.json"
    lock_path = output_dir / f"{STAGE}_LOCK.json"
    raw_outputs_path = output_dir / (
        "V5_P3_D2_RAW_NEURAL_VALIDATION_OUTPUTS.npz"
    )
    a0_outputs_path = output_dir / (
        "V5_P3_D2_FROZEN_P2_A0_VALIDATION_OUTPUTS.npz"
    )
    comparison_path = output_dir / (
        "V5_P3_D2_RAW_VS_FROZEN_A0_COMPARISON.json"
    )
    complete_path = output_dir / f"{STAGE}_COMPLETE"
    hold_path = output_dir / f"{STAGE}_HOLD"

    d1_dir = repo / "reports/v5/p3_d1_immutable_validation_logit_export"
    d1_report_path = d1_dir / (
        "V5_P3_D1_IMMUTABLE_TRANCHE_A_VALIDATION_LOGIT_EXPORT_REPORT.json"
    )
    d1_lock_path = d1_dir / (
        "V5_P3_D1_IMMUTABLE_TRANCHE_A_VALIDATION_LOGIT_EXPORT_LOCK.json"
    )
    export_path = d1_dir / (
        "V5_P3_D1_TRANCHE_A_VALIDATION_LOGITS_AND_LABELS.npz"
    )
    p2_evaluator_path = (
        repo
        / "scripts/v5/p2/evaluate_v5_p2_final_raw_a0_a1_one_shot.py"
    )
    l5_contract_path = (
        repo
        / "reports/v5/p2_l5_final_pretest_freeze/"
        "V5_P2_ONE_SHOT_BLIND_EVALUATION_CONTRACT.json"
    )

    required = [
        d1_report_path,
        d1_lock_path,
        export_path,
        p2_evaluator_path,
        l5_contract_path,
    ]
    missing = [str(path) for path in required if not path.is_file()]
    if missing:
        raise RuntimeError(f"required artifacts missing: {missing}")

    d1_report = json.loads(
        d1_report_path.read_text(encoding="utf-8")
    )
    d1_lock = json.loads(
        d1_lock_path.read_text(encoding="utf-8")
    )
    if d1_report.get("status") != "PASS":
        raise RuntimeError("D1 report is not PASS")
    if not d1_report.get("decision", {}).get(
        "raw_and_A0_evaluation_authorized"
    ):
        raise RuntimeError("D1 did not authorize Raw/A0 evaluation")
    if d1_lock.get("report_sha256") != sha256_file(
        d1_report_path
    ):
        raise RuntimeError("D1 report/lock SHA mismatch")
    if d1_lock.get("export_sha256") != sha256_file(export_path):
        raise RuntimeError("D1 export SHA mismatch")
    if d1_report.get("sealed_test", {}).get(
        "test_tensor_loaded"
    ):
        raise RuntimeError("D1 reports sealed-test access")

    p2_module = import_source(
        p2_evaluator_path,
        "_v5_p3_d2_p2_frozen_policy_source",
    )
    module_thresholds = dict(p2_module.A0_THRESHOLDS)
    for key, expected in EXPECTED_A0_THRESHOLDS.items():
        actual = float(module_thresholds[key])
        if actual != expected:
            raise RuntimeError(
                f"P2 evaluator A0 threshold changed for {key}: "
                f"{actual} != {expected}"
            )

    with np.load(export_path, allow_pickle=False) as loaded:
        arrays = {
            key: loaded[key].copy()
            for key in loaded.files
        }

    expected_shapes = {
        "attack_logits": (EXPECTED_ITEMS,),
        "count_logits": (EXPECTED_ITEMS, 4),
        "source_logits": (EXPECTED_ITEMS, 16),
        "transit_logits": (EXPECTED_ITEMS, 16),
        "victim_logits": (EXPECTED_ITEMS, 16),
        "path_logits": (EXPECTED_ITEMS, 16),
        "y_attack": (EXPECTED_ITEMS,),
        "y_attacker_count": (EXPECTED_ITEMS,),
        "y_source": (EXPECTED_ITEMS, 16),
        "y_transit": (EXPECTED_ITEMS, 16),
        "y_victim": (EXPECTED_ITEMS, 16),
        "y_attack_path": (EXPECTED_ITEMS, 16),
    }
    for key, shape in expected_shapes.items():
        if key not in arrays:
            raise RuntimeError(f"D1 export missing {key}")
        if arrays[key].shape != shape:
            raise RuntimeError(
                f"{key} shape={arrays[key].shape}, expected={shape}"
            )

    for key in (
        "attack_logits",
        "count_logits",
        "source_logits",
        "transit_logits",
        "victim_logits",
        "path_logits",
    ):
        if not np.isfinite(arrays[key]).all():
            raise RuntimeError(f"non-finite values in {key}")

    labels = {
        "graph": arrays["y_attack"].astype(np.uint8),
        "count": arrays["y_attacker_count"].astype(np.int8),
        "source": arrays["y_source"].astype(np.uint8),
        "transit": arrays["y_transit"].astype(np.uint8),
        "victim": arrays["y_victim"].astype(np.uint8),
        "path": arrays["y_attack_path"].astype(np.uint8),
    }

    raw_metrics, raw_outputs = evaluate_policy(
        "Raw neural threshold-0.5 heads",
        graph_threshold=0.5,
        role_thresholds={
            "source": 0.5,
            "transit": 0.5,
            "victim": 0.5,
            "path": 0.5,
        },
        arrays=arrays,
        labels=labels,
    )
    a0_metrics, a0_outputs = evaluate_policy(
        "Frozen P2 A0 threshold transfer",
        graph_threshold=EXPECTED_A0_THRESHOLDS["graph"],
        role_thresholds={
            role: EXPECTED_A0_THRESHOLDS[role]
            for role in ("source", "transit", "victim", "path")
        },
        arrays=arrays,
        labels=labels,
    )

    # Raw graph metrics must reproduce D1/A5 because Raw uses threshold 0.5.
    d1_metric = d1_report["metric_certification"]
    raw_consistency = {
        "graph_f1_delta_vs_D1": abs(
            raw_metrics["graph"]["f1"]
            - float(
                d1_metric["graph_threshold_0p5"]["f1"]
